package sv.edu.udb.pokebattle.dto; import java.util.UUID; import sv.edu.udb.pokebattle.model.PokemonBatalla; public record PokemonBatallaResponse(UUID pokemonBatallaId,UUID pokemonEquipoId,String nombre,String sprite,Integer vidaActual,Integer vidaMaxima,boolean activo,boolean debilitado) { public static PokemonBatallaResponse desde(PokemonBatalla p){return new PokemonBatallaResponse(p.getId(),p.getPokemonEquipo().getId(),p.getPokemonEquipo().getNombre(),p.getPokemonEquipo().getSprite(),p.getVidaActual(),p.getPokemonEquipo().getHpBase(),p.isActivo(),p.isDebilitado());} }
